// Запуск — «Пробел» на видео (клик по центру плеера в headless Chromium не запускает, см. startDesktop).
import { test } from '@playwright/test';
import { prepareReadOnly, GUIDES, openGuides, videoOf, mp4Response, startDesktop, expectPlaying, expectPlaysWithSound, stop } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test.describe('Видео-инструкции /guides — воспроизведение', () => {
  for (const g of GUIDES) {
    test(`${g.id}: по нажатию видео играет со звуком (не muted), mp4 200/206 #8790d6 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openGuides(page);
      const video = videoOf(page, g);

      const resp = mp4Response(page, g);
      await startDesktop(page, video);
      const r = await resp;
      await expectPlaying(video, 1, g.id);
      await expectPlaysWithSound(video, r, g);
      await stop(video);
    });
  }
});
